# transpose :: [[1, 2, 3], [4, 5, 6]]
def transpose(m):
    if not m:
        return []
    return [list(row) for row in zip(*m)]

if __name__ == "__main__":
    print(transpose([[1, 2, 3], [4, 5, 6]]))

